import{_ as t,o,c as r,a1 as d}from"./chunks/framework.Ccs17H5l.js";const s="/eadkp/assets/eif1-format-v3.DQWe5cEQ.jpg",g=JSON.parse('{"title":"EIF1","description":"","frontmatter":{},"headers":[],"relativePath":"old-docs/TECHNICALS/EIF/EIF1.md","filePath":"old-docs/TECHNICALS/EIF/EIF1.md"}'),i={name:"old-docs/TECHNICALS/EIF/EIF1.md"};function c(a,e,n,u,l,p){return o(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="eif1" tabindex="-1">EIF1 <a class="header-anchor" href="#eif1" aria-label="Permalink to &quot;EIF1&quot;">​</a></h1><h2 id="specifications-de-la-version-1" tabindex="-1">Spécifications de la version 1 <a class="header-anchor" href="#specifications-de-la-version-1" aria-label="Permalink to &quot;Spécifications de la version 1&quot;">​</a></h2><ul><li><p><strong>Magic Number</strong> : <code>0x31464945</code> — <code>EIF1</code> (ASCII) sur 4 premiers octets</p></li><li><p><strong>Transparence</strong> : Non supportée</p></li><li><p><strong>Format initial</strong> : Première version du format EIF</p></li><li><p><strong>Structure du fichier</strong> : En-tête suivi des données d&#39;image en RGB 565</p></li></ul><h2 id="structure-du-fichier" tabindex="-1">Structure du fichier <a class="header-anchor" href="#structure-du-fichier" aria-label="Permalink to &quot;Structure du fichier&quot;">​</a></h2><p>Structure de fichier Format EIF1 (Eadkp. Image. Format. 1.) :</p><table tabindex="0"><thead><tr><th><strong>Nom</strong></th><th><strong>Adresse</strong></th><th><strong>Taille</strong></th><th><strong>Description</strong></th></tr></thead><tbody><tr><td><strong>Magic Number</strong></td><td><code>0x000</code> — <code>0x003</code></td><td>4 Octets</td><td>Nombre d&#39;identification du format du fichier (<code>0x31464945</code> en hex, correspond à &quot;EIF1&quot; en ASCII)</td></tr><tr><td><strong>Width</strong></td><td><code>0x004</code> — <code>0x005</code></td><td>2 Octets</td><td>Largeur de l&#39;image en pixels, format <code>u16</code> (entier non signé sur 2 octets en Big-endian)</td></tr><tr><td><strong>Height</strong></td><td><code>0x006</code> — <code>0x007</code></td><td>2 Octets</td><td>Hauteur de l&#39;image en pixels, format <code>u16</code> (entier non signé sur 2 octets en Big-endian)</td></tr><tr><td><strong>Pixels (data)</strong></td><td><code>0x008</code> — <code>0x007 + (N_pixels × 2)</code></td><td>N pixels × 2 Octets</td><td>Données des pixels, format <code>RGB565</code> (chaque pixel sur 2 octets). Chaque pixel est un <code>u16</code>. N_pixels × 2 Octets.</td></tr></tbody></table><ul><li><p>Le Magic Number est stocké en big-endian sur les 4 premiers octets du fichier.</p></li><li><p>La largeur puis la hauteur de l&#39;image sont stockées en big-endian sur 2 octets chacun, juste après le Magic Number.</p></li><li><p>Les données des pixels suivent immédiatement l&#39;en-tête, chaque pixel étant représenté en format <code>RGB565</code> sur 2 octets. Le nombre total d&#39;octets pour les données des pixels est égal à <code>Largeur × Hauteur × 2</code>.</p></li></ul><p>L&#39;en-tête du fichier occupe donc un total de 8 octets, suivi des données des pixels qui occupent <code>Largeur × Hauteur × 2</code> octets.</p><hr><p>Comme tout ceci n&#39;est pas très parlant, voici un schéma explicatif de la structure du fichier EIF1 :</p><p><img src="'+s+'" alt="Schéma de la structure du fichier EIF1"></p>',11)])])}const m=t(i,[["render",c]]);export{g as __pageData,m as default};
